<?php
defined('BASEPATH') or exit('No direct script access allowed');

/** CSV reference import. Technical batch identity is generated by the application. */
class Zahir_snapshot_validator
{
    const MAX_BYTES = 5242880;
    const MAX_ROWS = 10000;

    public function decode($bytes, $extension, array $metadata = [])
    {
        if ($extension !== 'csv') throw new RuntimeException('Hanya file CSV referensi Zahir yang diterima.');
        if (strlen($bytes) > self::MAX_BYTES || !preg_match('//u', $bytes)) throw new RuntimeException('File maksimum 5 MiB dan wajib UTF-8.');
        $bytes = preg_replace('/^\xEF\xBB\xBF/', '', $bytes);
        $h = fopen('php://temp', 'w+');
        try {
            fwrite($h, $bytes); rewind($h);
            $header = fgetcsv($h);
            $full = ['kode_barang','nama_barang','expired_date','qty_lot','p','l','t'];
            $core = array_slice($full, 0, 4);
            if ($header !== $full && $header !== $core) throw new RuntimeException('Header CSV harus kode_barang,nama_barang,expired_date,qty_lot dengan opsional p,l,t.');
            $rows = [];
            while (($r = fgetcsv($h)) !== false) {
                if (count($r) !== count($header)) throw new RuntimeException('Jumlah kolom salah pada baris CSV '.(count($rows)+2));
                // Deliberately discard dimensions, including invalid values.
                $rows[] = array_combine($core, array_slice($r, 0, 4));
                if (count($rows) > self::MAX_ROWS) throw new RuntimeException('Maksimum 10000 baris.');
            }
        } finally { fclose($h); }
        $metadata['rows'] = $rows;
        return $this->validate($metadata);
    }

    public function validate($d)
    {
        if (!is_array($d) || empty($d['rows']) || !is_array($d['rows']) || count($d['rows']) > self::MAX_ROWS || array_keys($d['rows']) !== range(0,count($d['rows'])-1)) throw new RuntimeException('CSV kosong atau jumlah baris tidak sah; referensi lama dipertahankan.');
        foreach (['source_instance','scope'] as $k) {
            if (!is_string($d[$k] ?? null) || !preg_match('/^[A-Za-z0-9_.:\/-]{1,128}$/D',$d[$k])) throw new RuntimeException('Konfigurasi '.$k.' tidak valid.');
        }
        if (empty($d['snapshot_id'])) {
            $uuid = bin2hex(random_bytes(16));
            $d['snapshot_id'] = substr($uuid,0,8).'-'.substr($uuid,8,4).'-4'.substr($uuid,13,3).'-a'.substr($uuid,17,3).'-'.substr($uuid,20,12);
        }
        if (!is_string($d['snapshot_id']) || !preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iD',$d['snapshot_id'])) throw new RuntimeException('Identitas impor tidak valid.');
        $d['snapshot_id'] = strtolower($d['snapshot_id']);
        $d['input_format'] = 'csv-v1';
        $d['row_count'] = count($d['rows']);
        $d['exported_at'] = null; // Upload time must never masquerade as source time.
        $errors=[]; $valid=[]; $seen=[]; $names=[]; $duplicates=0;
        foreach ($d['rows'] as $i=>$r) {
            $e=[];
            if (!is_array($r)) { $errors[]=['row'=>$i+1,'errors'=>['Row wajib objek.']]; continue; }
            $code=$r['kode_barang']??null; $name=$r['nama_barang']??null;
            if (!is_string($code) || !is_string($name)) { $errors[]=['row'=>$i+1,'errors'=>['Kode dan nama wajib teks.']]; continue; }
            if (!preg_match('/^[A-Za-z0-9_.:\/ -]{1,25}$/D',$code) || trim($code)==='') $e[]='Kode wajib ASCII nonkosong maksimal 25 karakter.';
            if (strlen($name)>65535 || preg_match('/[\x00-\x1f]/',$name) || $this->name($name)==='') $e[]='Nama tidak valid.';
            $date=$r['expired_date']??null;
            $parsed=is_string($date)?DateTime::createFromFormat('!Y-m-d',$date):false;
            if (!$parsed || $parsed->format('Y-m-d')!==$date || $date<'1000-01-01') $e[]='Expired kosong/tidak valid; wajib YYYY-MM-DD.';
            $qty=$r['qty_lot']??null;
            if (!is_string($qty) || !preg_match('/^-?(?:0|[1-9][0-9]{0,17})(?:\.[0-9]{1,6})?$/D',$qty)) $e[]='Qty wajib desimal bertitik, maksimum 18 digit bulat dan 6 pecahan.';
            $key=strtoupper(trim($code)).'|'.(is_string($date)?$date:'');
            if (isset($seen[$key])) { $e[]='Duplikat grain kode/expired.'; $duplicates++; } $seen[$key]=true;
            $ck=strtoupper(trim($code)); $normalized=$this->name($name);
            if (isset($names[$ck]) && $names[$ck]!==$normalized) $e[]='Konflik nama antar expired untuk kode yang sama.';
            $names[$ck]=$normalized;
            if ($e) $errors[]=['row'=>$i+1,'errors'=>$e];
            else $valid[]=['kode_barang'=>$code,'nama_barang'=>$name,'nama_normalized'=>$normalized,'expired_date'=>$date,'qty_lot'=>$qty];
        }
        return ['document'=>$d,'rows'=>$valid,'errors'=>$errors,'duplicates'=>$duplicates,'source_count'=>count($d['rows']),'valid_count'=>count($valid),'exported_epoch'=>null];
    }
    public function name($s) { return trim(preg_replace('/\s+/u',' ',str_replace('*','',$s))); }
}
